text:
{
  "filename": "style.css",
  "content": "body {
  font-family: Arial;
  color: #333;
  background-color: #f0f0f0;
}

header {
  background-color: #4CAF50;
  padding: 10px;
  text-align: center;
}

nav ul {
  list-style-type: none;
  padding: 0;
}

nav ul li {
  display: inline;
  margin: 0 10px;
}

nav ul li a {
  color: white;
  text-decoration: none;
}

nav ul li a:hover {
  background-color: #45a049;
}

header h1, h2 {
  color: white;
}

section {
  padding: 20px;
}

button {
  background-color: #4CAF50;
  color: white;
  padding: 10px 20px;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

button:hover {
  background-color: #45a049;
}
"
}
